package com.cryptostrategy.platform.persistence.backtesting;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.persistence.api.BacktestingPersistenceFactory;import com.cryptostrategy.platform.persistence.support.F006DatabaseFixture;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;
class JdbcBacktestResultStoreIntegrationTest{@Test void atomicallyPersistsReadsAndReusesCandidateOutcome(){var source=F006DatabaseFixture.dataSource();var tx=F006DatabaseFixture.transaction(source);tx.executeWithoutResult(status->{status.setRollbackOnly();var jdbc=new JdbcTemplate(source);F006DatabaseFixture.seed(jdbc);var factory=new BacktestingPersistenceFactory(source);var result=F006DatabaseFixture.result();assertEquals(result,factory.createResultStore().save(result));var loaded=factory.createResultReader().findById(result.resultId()).orElseThrow();assertEquals(result.fingerprint(),loaded.fingerprint());assertEquals(result.trades(),loaded.trades());factory.createResultStore().save(result);assertEquals(1,jdbc.queryForObject("select count(*) from experiment.backtest_result where candidate_id=?",Integer.class,F006DatabaseFixture.CANDIDATE));assertEquals(5,jdbc.queryForObject("select count(*) from experiment.trade where backtest_result_id=?",Integer.class,F006DatabaseFixture.RESULT));});}}
